let quine;
let i = 0;
let t = 0;
let lines = [""];
let charIndex = 0;
let typeSpeed = 4;
let cursorBlinkSpeed = 30;
let tbg = 0;
let direction = 1;

function setup() {
  createCanvas(400, 400);
  background(15);
  textFont("monospace");
  textSize(12);
  quine = draw.toString().split("");
}

function draw() {
  let val = map(tbg,0,1,1,200)
  fill(15,val);
  noStroke();
  rect(0, 0, width, height);

  let x = width / 2;
  let y = height / 2;
  let margin = 12;

  let visible = quine.slice(0, i);

  for (let c = 0; c < visible.length; c++) {
    let ch = visible[c];
    let angle = noise(x * 0.01, y * 0.01, t) * TWO_PI * 4;

    x += cos(angle) * margin;
    y += sin(angle) * margin;

    if (x > width) x = 0;
    if (x < 0) x = width;
    if (y > height) y = 0;
    if (y < 0) y = height;

    fill(230);
    stroke(255, 255, 0);
    strokeWeight(0.2);
    text(ch, x, y);
  }

  let boxW = 200;
  let boxH = 120;
  let padding = 10;
  let lineH = 14;

  let boxX = width - boxW - 20;
  let boxY = height - boxH - 20;

  let maxLines = floor((boxH - padding * 2) / lineH);

  noFill();
  stroke(255);
  rect(boxX, boxY, boxW, boxH);

  if (frameCount % typeSpeed === 0 && charIndex < quine.length) {
    let ch = quine[charIndex];

    if (ch === "\n") {
      lines.push("");
    } else {
      let testLint = lines[lines.length - 1] + ch;
      if (textWidth(testLint) > boxW - padding * 2) {
        lines.push(ch);
      } else {
        lines[lines.length - 1] = testLint;
      }
    }

    if (lines.length > maxLines) lines.shift();
    charIndex++;
  }

  push();
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.rect(boxX, boxY, boxW, boxH);
  drawingContext.clip();

  let ty = boxY + padding + lineH;

  for (let i = 0; i < lines.length; i++) {
    let lint = lines[i];

    for (let c = 0; c < lint.length; c++) {
      let nx = noise(c * 0.05, frameCount * 0.02) - 0.5;
      let ny = noise(c * 0.05 + 100, frameCount * 0.02) - 0.5;

      let tx =
        boxX +
        padding +
        textWidth(lint.substring(0, c));

      textSize(10);
      text(lint[c], tx + nx * 2, ty + ny * 2);
    }

    ty += lineH;
  }

  if (frameCount % cursorBlinkSpeed < cursorBlinkSpeed / 2) {
    let lastLint = lines[lines.length - 1];

    let cursorX =
      boxX +
      padding +
      textWidth(lastLint);

    let cursorY = ty - lineH;

    fill(255);
    rect(cursorX, cursorY - lineH + 3, 6, lineH);
  }

  drawingContext.restore();
  pop();

  if (i < quine.length) i++;
  t += 0.01;
  tbg += 0.05 * direction;
  if (tbg >= 1) {
    direction = -1;
  } else if (tbg <= 0) {
    direction = 1;
  } 
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
